extract-structured-data.beforeRequest:
const properties = {};
const required = [];
for (const field of JSON.parse(inputs.params)) {
  properties[field.propName] = { type: field.propDataType, description: field.propDescription ?? field.propName };
  if (field.propIsRequired) required.push(field.propName);
}
request.body.messages = [{ role: 'user', content: inputs.text }];
request.body.tools = [{ type: 'function', function: { name: 'extract_structured_data', description: 'Extract the following data from the provided text', parameters: { type: 'object', properties, required } } }];
return request;

extract-structured-data.afterResponse:
const calls = response.choices[0].message.tool_calls;
if (!calls || calls.length === 0) throw new Error(JSON.stringify({ message: "OpenAI couldn't extract the fields from the above text." }));
const raw = calls[0].function.arguments;
try {
  return JSON.parse(raw);
} catch (e) {
  throw new Error(JSON.stringify({ message: 'OpenAI returned invalid JSON for the extracted fields.', raw }));
}

analyze_sentiment.afterResponse:
const content = response.choices[0]?.message.content ?? '{}';
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { explanation: content };
}
const label = String(parsed.sentiment ?? '').toLowerCase();
const sentiment = ['positive', 'negative', 'neutral'].find((known) => known === label) ?? 'neutral';
const confidence = typeof parsed.confidence === 'number' && parsed.confidence >= 0 && parsed.confidence <= 1 ? parsed.confidence : undefined;
return { sentiment, confidence, explanation: typeof parsed.explanation === 'string' ? parsed.explanation : undefined };

search_embeddings.beforeRequest:
const texts = [inputs.query, ...JSON.parse(inputs.documents).map(String)];
request.body.input = texts.slice(0, 2048);
return request;

search_embeddings.afterResponse:
const documents = JSON.parse(inputs.documents).map(String);
const texts = [inputs.query, ...documents];
const vectors = response.data.map((item) => item.embedding);
let tokens = response.usage?.total_tokens ?? 0;
for (let start = 2048; start < texts.length; start += 2048) {
  const page = call({ method: 'POST', url: '/embeddings', body: { model: inputs.model, input: texts.slice(start, start + 2048) } });
  vectors.push(...page.data.map((item) => item.embedding));
  tokens += page.usage?.total_tokens ?? 0;
}
const cosine = (a, b) => {
  let dot = 0, normA = 0, normB = 0;
  for (let index = 0; index < a.length; index++) { dot += a[index] * b[index]; normA += a[index] * a[index]; normB += b[index] * b[index]; }
  const norm = Math.sqrt(normA) * Math.sqrt(normB);
  return norm === 0 ? 0 : dot / norm;
};
const [query, ...rest] = vectors;
const ranked = rest.map((vector, index) => ({ document: documents[index], index, score: cosine(query, vector) })).sort((a, b) => b.score - a.score);
const topK = inputs.topK === '' ? NaN : Number(inputs.topK);
const results = topK > 0 ? ranked.slice(0, topK) : ranked;
return { bestMatch: results[0] ?? null, results, usage: { total_tokens: tokens } };

find_file.afterResponse:
const name = inputs.fileName.toLowerCase();
const files = response.data.filter((file) => file.filename.toLowerCase() === name);
return { found: files.length > 0, count: files.length, file: files[0] ?? null, files };

list_models.afterResponse:
const models = response.data ?? [];
const contains = inputs.contains.toLowerCase().trim();
const found = contains ? models.filter((model) => model.id.toLowerCase().includes(contains)) : models;
return { count: found.length, models: found.map((model) => ({ id: model.id, created: model.created, owned_by: model.owned_by })) };
